module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

    logic        aw_full, w_full;
    logic [3:0]  aw_addr;
    logic [31:0] w_data;
    logic [3:0]  w_strb;
    logic [31:0] ctrl, scratch, irq;

    logic        commit;
    logic [31:0] bmask;
    logic [31:0] clr_mask;

    assign s_axi_awready = !aw_full && !s_axi_bvalid && !rst;
    assign s_axi_wready  = !w_full  && !s_axi_bvalid && !rst;
    assign s_axi_arready = !s_axi_rvalid && !rst;

    assign commit = aw_full && w_full;

    always_comb begin
        bmask = {{8{w_strb[3]}}, {8{w_strb[2]}}, {8{w_strb[1]}}, {8{w_strb[0]}}};
        clr_mask = 32'd0;
        if (commit && aw_addr == 4'hC) clr_mask = w_data & bmask;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            aw_full      <= 1'b0;
            w_full       <= 1'b0;
            aw_addr      <= 4'd0;
            w_data       <= 32'd0;
            w_strb       <= 4'd0;
            ctrl         <= 32'd0;
            scratch      <= 32'd0;
            irq          <= 32'd0;
            s_axi_bvalid <= 1'b0;
            s_axi_bresp  <= 2'b00;
            s_axi_rvalid <= 1'b0;
            s_axi_rdata  <= 32'd0;
            s_axi_rresp  <= 2'b00;
        end else begin
            irq <= (irq & ~clr_mask) | irq_set;

            // write address / data slots
            if (s_axi_awvalid && s_axi_awready) begin
                aw_full <= 1'b1;
                aw_addr <= s_axi_awaddr;
            end
            if (s_axi_wvalid && s_axi_wready) begin
                w_full <= 1'b1;
                w_data <= s_axi_wdata;
                w_strb <= s_axi_wstrb;
            end

            if (commit) begin
                aw_full      <= 1'b0;
                w_full       <= 1'b0;
                s_axi_bvalid <= 1'b1;
                case (aw_addr)
                    4'h0: begin
                        ctrl        <= (ctrl & ~bmask) | (w_data & bmask);
                        s_axi_bresp <= 2'b00;
                    end
                    4'h8: begin
                        scratch     <= (scratch & ~bmask) | (w_data & bmask);
                        s_axi_bresp <= 2'b00;
                    end
                    4'hC: s_axi_bresp <= 2'b00;
                    default: s_axi_bresp <= 2'b10;
                endcase
            end else if (s_axi_bvalid && s_axi_bready) begin
                s_axi_bvalid <= 1'b0;
            end

            // read channel
            if (s_axi_arvalid && s_axi_arready) begin
                s_axi_rvalid <= 1'b1;
                case (s_axi_araddr)
                    4'h0: begin s_axi_rdata <= ctrl;      s_axi_rresp <= 2'b00; end
                    4'h4: begin s_axi_rdata <= status_in; s_axi_rresp <= 2'b00; end
                    4'h8: begin s_axi_rdata <= scratch;   s_axi_rresp <= 2'b00; end
                    4'hC: begin s_axi_rdata <= irq;       s_axi_rresp <= 2'b00; end
                    default: begin s_axi_rdata <= 32'd0;  s_axi_rresp <= 2'b10; end
                endcase
            end else if (s_axi_rvalid && s_axi_rready) begin
                s_axi_rvalid <= 1'b0;
            end
        end
    end

    logic unused;
    assign unused = &{1'b0, s_axi_awprot, s_axi_arprot};

endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
