    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);
    logic        aw_full, w_full;
    logic [3:0]  aw_addr_q;
    logic [31:0] wdata_q;
    logic [3:0]  wstrb_q;
    logic [31:0] ctrl, scratch, irq;

    logic [31:0] wmask;
    logic [31:0] clear_mask;
    logic        commit;

    assign s_axi_awready = !aw_full && !s_axi_bvalid && !rst;
    assign s_axi_wready  = !w_full  && !s_axi_bvalid && !rst;
    assign s_axi_arready = !s_axi_rvalid && !rst;

    assign wmask = {{8{wstrb_q[3]}}, {8{wstrb_q[2]}}, {8{wstrb_q[1]}}, {8{wstrb_q[0]}}};
    assign commit = aw_full && w_full;
    assign clear_mask = wdata_q & wmask;

    always_ff @(posedge clk) begin
        if (rst) begin
            aw_full      <= 1'b0;
            w_full       <= 1'b0;
            aw_addr_q    <= 4'd0;
            wdata_q      <= 32'd0;
            wstrb_q      <= 4'd0;
            ctrl         <= 32'd0;
            scratch      <= 32'd0;
            irq          <= 32'd0;
            s_axi_bvalid <= 1'b0;
            s_axi_bresp  <= 2'b00;
            s_axi_rvalid <= 1'b0;
            s_axi_rdata  <= 32'd0;
            s_axi_rresp  <= 2'b00;
        end else begin
            // IRQ: set always, clear on commit
            irq <= (irq & ~((commit && aw_addr_q == 4'hC) ? clear_mask : 32'd0)) | irq_set;

            // Write address / data capture
            if (s_axi_awvalid && s_axi_awready) begin
                aw_full   <= 1'b1;
                aw_addr_q <= s_axi_awaddr;
            end
            if (s_axi_wvalid && s_axi_wready) begin
                w_full  <= 1'b1;
                wdata_q <= s_axi_wdata;
                wstrb_q <= s_axi_wstrb;
            end

            // Commit
            if (commit) begin
                aw_full      <= 1'b0;
                w_full       <= 1'b0;
                s_axi_bvalid <= 1'b1;
                case (aw_addr_q)
                    4'h0: begin
                        ctrl        <= (ctrl & ~wmask) | (wdata_q & wmask);
                        s_axi_bresp <= 2'b00;
                    end
                    4'h8: begin
                        scratch     <= (scratch & ~wmask) | (wdata_q & wmask);
                        s_axi_bresp <= 2'b00;
                    end
                    4'hC: s_axi_bresp <= 2'b00;
                    default: s_axi_bresp <= 2'b10;
                endcase
            end else if (s_axi_bvalid && s_axi_bready) begin
                s_axi_bvalid <= 1'b0;
            end

            // Read
            if (s_axi_arvalid && s_axi_arready) begin
                s_axi_rvalid <= 1'b1;
                case (s_axi_araddr)
                    4'h0: begin s_axi_rdata <= ctrl;      s_axi_rresp <= 2'b00; end
                    4'h4: begin s_axi_rdata <= status_in; s_axi_rresp <= 2'b00; end
                    4'h8: begin s_axi_rdata <= scratch;   s_axi_rresp <= 2'b00; end
                    4'hC: begin s_axi_rdata <= irq;       s_axi_rresp <= 2'b00; end
                    default: begin s_axi_rdata <= 32'd0;  s_axi_rresp <= 2'b10; end
                endcase
            end else if (s_axi_rvalid && s_axi_rready) begin
                s_axi_rvalid <= 1'b0;
            end
        end
    end
endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

    logic [31:0] ctrl, scratch, irq;
    logic        aw_full, w_full;
    logic [3:0]  aw_addr;
    logic [31:0] w_data;
    logic [3:0]  w_strb;

    logic [31:0] strb_mask;
    logic [31:0] merged_ctrl, merged_scratch;
    logic [31:0] clear_mask;
    logic        commit;
    logic        aw_ok;
    logic        ar_ok;
    logic [31:0] rd_val;

    wire aw_hs = s_axi_awvalid && s_axi_awready;
    wire w_hs  = s_axi_wvalid  && s_axi_wready;
    wire ar_hs = s_axi_arvalid && s_axi_arready;

    assign s_axi_awready = !aw_full && !s_axi_bvalid && !rst;
    assign s_axi_wready  = !w_full  && !s_axi_bvalid && !rst;
    assign s_axi_arready = !s_axi_rvalid && !rst;

    assign commit = aw_full && w_full && !s_axi_bvalid;

    always_comb begin
        for (int i = 0; i < 4; i++)
            strb_mask[8*i +: 8] = {8{w_strb[i]}};
        merged_ctrl    = (ctrl    & ~strb_mask) | (w_data & strb_mask);
        merged_scratch = (scratch & ~strb_mask) | (w_data & strb_mask);
        clear_mask     = w_data & strb_mask;
        aw_ok = (aw_addr[1:0] == 2'b00) && (aw_addr[3:2] != 2'b01);
        ar_ok = (s_axi_araddr[1:0] == 2'b00);
        case (s_axi_araddr[3:2])
            2'd0:    rd_val = ctrl;
            2'd1:    rd_val = status_in;
            2'd2:    rd_val = scratch;
            default: rd_val = irq;
        endcase
        if (!ar_ok) rd_val = 32'd0;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            ctrl         <= 32'd0;
            scratch      <= 32'd0;
            irq          <= 32'd0;
            aw_full      <= 1'b0;
            w_full       <= 1'b0;
            aw_addr      <= 4'd0;
            w_data       <= 32'd0;
            w_strb       <= 4'd0;
            s_axi_bvalid <= 1'b0;
            s_axi_bresp  <= 2'b00;
            s_axi_rvalid <= 1'b0;
            s_axi_rdata  <= 32'd0;
            s_axi_rresp  <= 2'b00;
        end else begin
            // IRQ: set always, clear on commit write
            irq <= (irq & ~((commit && aw_ok && aw_addr[3:2] == 2'd3) ? clear_mask : 32'd0)) | irq_set;

            // write slots
            if (aw_hs) begin
                aw_full <= 1'b1;
                aw_addr <= s_axi_awaddr;
            end
            if (w_hs) begin
                w_full <= 1'b1;
                w_data <= s_axi_wdata;
                w_strb <= s_axi_wstrb;
            end

            if (commit) begin
                aw_full      <= 1'b0;
                w_full       <= 1'b0;
                s_axi_bvalid <= 1'b1;
                s_axi_bresp  <= aw_ok ? 2'b00 : 2'b10;
                if (aw_ok) begin
                    case (aw_addr[3:2])
                        2'd0:    ctrl    <= merged_ctrl;
                        2'd2:    scratch <= merged_scratch;
                        default: ;
                    endcase
                end
            end else if (s_axi_bvalid && s_axi_bready) begin
                s_axi_bvalid <= 1'b0;
            end

            // read
            if (ar_hs) begin
                s_axi_rvalid <= 1'b1;
                s_axi_rdata  <= rd_val;
                s_axi_rresp  <= ar_ok ? 2'b00 : 2'b10;
            end else if (s_axi_rvalid && s_axi_rready) begin
                s_axi_rvalid <= 1'b0;
            end
        end
    end

endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

    logic [31:0] ctrl, scratch, irq;
    logic        aw_full, w_full;
    logic [3:0]  aw_addr_q;
    logic [31:0] wdata_q;
    logic [3:0]  wstrb_q;

    logic [1:0]  bresp_q, rresp_q;
    logic        bvalid_q, rvalid_q;
    logic [31:0] rdata_q;

    assign s_axi_awready = !aw_full && !bvalid_q && !rst;
    assign s_axi_wready  = !w_full  && !bvalid_q && !rst;
    assign s_axi_arready = !rvalid_q && !rst;
    assign s_axi_bresp   = bresp_q;
    assign s_axi_bvalid  = bvalid_q;
    assign s_axi_rdata   = rdata_q;
    assign s_axi_rresp   = rresp_q;
    assign s_axi_rvalid  = rvalid_q;

    logic        commit;
    logic [31:0] bmask;
    logic [31:0] clr_mask;

    assign commit = aw_full && w_full;
    assign bmask = {{8{wstrb_q[3]}}, {8{wstrb_q[2]}}, {8{wstrb_q[1]}}, {8{wstrb_q[0]}}};
    assign clr_mask = (commit && aw_addr_q == 4'hC) ? (wdata_q & bmask) : 32'h0;

    always_ff @(posedge clk) begin
        if (rst) begin
            ctrl     <= 32'h0;
            scratch  <= 32'h0;
            irq      <= 32'h0;
            aw_full  <= 1'b0;
            w_full   <= 1'b0;
            aw_addr_q <= 4'h0;
            wdata_q  <= 32'h0;
            wstrb_q  <= 4'h0;
            bvalid_q <= 1'b0;
            bresp_q  <= 2'b00;
            rvalid_q <= 1'b0;
            rdata_q  <= 32'h0;
            rresp_q  <= 2'b00;
        end else begin
            irq <= (irq & ~clr_mask) | irq_set;

            // write address / data capture
            if (s_axi_awvalid && s_axi_awready) begin
                aw_full   <= 1'b1;
                aw_addr_q <= s_axi_awaddr;
            end
            if (s_axi_wvalid && s_axi_wready) begin
                w_full  <= 1'b1;
                wdata_q <= s_axi_wdata;
                wstrb_q <= s_axi_wstrb;
            end

            if (commit) begin
                aw_full  <= 1'b0;
                w_full   <= 1'b0;
                bvalid_q <= 1'b1;
                case (aw_addr_q)
                    4'h0: begin
                        ctrl    <= (ctrl & ~bmask) | (wdata_q & bmask);
                        bresp_q <= 2'b00;
                    end
                    4'h8: begin
                        scratch <= (scratch & ~bmask) | (wdata_q & bmask);
                        bresp_q <= 2'b00;
                    end
                    4'hC: bresp_q <= 2'b00;
                    default: bresp_q <= 2'b10;
                endcase
            end else if (bvalid_q && s_axi_bready) begin
                bvalid_q <= 1'b0;
            end

            // read
            if (s_axi_arvalid && s_axi_arready) begin
                rvalid_q <= 1'b1;
                case (s_axi_araddr)
                    4'h0: begin rdata_q <= ctrl;      rresp_q <= 2'b00; end
                    4'h4: begin rdata_q <= status_in; rresp_q <= 2'b00; end
                    4'h8: begin rdata_q <= scratch;   rresp_q <= 2'b00; end
                    4'hC: begin rdata_q <= irq;       rresp_q <= 2'b00; end
                    default: begin rdata_q <= 32'h0;  rresp_q <= 2'b10; end
                endcase
            end else if (rvalid_q && s_axi_rready) begin
                rvalid_q <= 1'b0;
            end
        end
    end

    logic unused;
    assign unused = &{1'b0, s_axi_awprot, s_axi_arprot};

endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

    logic        aw_full, w_full;
    logic [3:0]  aw_addr_q;
    logic [31:0] wdata_q;
    logic [3:0]  wstrb_q;
    logic [31:0] ctrl, scratch, irq;
    logic [31:0] wmask;
    logic [31:0] clr;

    logic aw_hs, w_hs, ar_hs, commit;

    assign s_axi_awready = !aw_full && !s_axi_bvalid && !rst;
    assign s_axi_wready  = !w_full  && !s_axi_bvalid && !rst;
    assign s_axi_arready = !s_axi_rvalid && !rst;

    assign aw_hs  = s_axi_awvalid && s_axi_awready;
    assign w_hs   = s_axi_wvalid  && s_axi_wready;
    assign ar_hs  = s_axi_arvalid && s_axi_arready;
    assign commit = aw_full && w_full;

    assign wmask = {{8{wstrb_q[3]}}, {8{wstrb_q[2]}}, {8{wstrb_q[1]}}, {8{wstrb_q[0]}}};
    assign clr   = wdata_q & wmask;

    always_ff @(posedge clk) begin
        if (rst) begin
            aw_full      <= 1'b0;
            w_full       <= 1'b0;
            aw_addr_q    <= 4'd0;
            wdata_q      <= 32'd0;
            wstrb_q      <= 4'd0;
            ctrl         <= 32'd0;
            scratch      <= 32'd0;
            irq          <= 32'd0;
            s_axi_bvalid <= 1'b0;
            s_axi_bresp  <= 2'b00;
            s_axi_rvalid <= 1'b0;
            s_axi_rdata  <= 32'd0;
            s_axi_rresp  <= 2'b00;
        end else begin
            irq <= irq | irq_set;

            if (aw_hs) begin
                aw_full   <= 1'b1;
                aw_addr_q <= s_axi_awaddr;
            end
            if (w_hs) begin
                w_full  <= 1'b1;
                wdata_q <= s_axi_wdata;
                wstrb_q <= s_axi_wstrb;
            end

            if (commit) begin
                aw_full      <= 1'b0;
                w_full       <= 1'b0;
                s_axi_bvalid <= 1'b1;
                s_axi_bresp  <= 2'b00;
                case (aw_addr_q)
                    4'h0: ctrl    <= (ctrl & ~wmask) | (wdata_q & wmask);
                    4'h8: scratch <= (scratch & ~wmask) | (wdata_q & wmask);
                    4'hC: irq     <= (irq & ~clr) | irq_set;
                    default: s_axi_bresp <= 2'b10;
                endcase
            end else if (s_axi_bvalid && s_axi_bready) begin
                s_axi_bvalid <= 1'b0;
            end

            if (ar_hs) begin
                s_axi_rvalid <= 1'b1;
                s_axi_rresp  <= 2'b00;
                case (s_axi_araddr)
                    4'h0: s_axi_rdata <= ctrl;
                    4'h4: s_axi_rdata <= status_in;
                    4'h8: s_axi_rdata <= scratch;
                    4'hC: s_axi_rdata <= irq;
                    default: begin
                        s_axi_rdata <= 32'd0;
                        s_axi_rresp <= 2'b10;
                    end
                endcase
            end else if (s_axi_rvalid && s_axi_rready) begin
                s_axi_rvalid <= 1'b0;
            end
        end
    end

    logic unused;
    assign unused = &{1'b0, s_axi_awprot, s_axi_arprot};

endmodule

module crc32_stream (
    input  logic        clk,
    input  logic        rst,
    input  logic        start,
    input  logic        in_valid,
    input  logic [7:0]  data,
    output logic        out_valid,
    output logic [31:0] crc
);

    logic [31:0] rem_q;
    logic [31:0] base;
    logic [31:0] nxt;

    always_comb begin
        base = start ? 32'hFFFF_FFFF : rem_q;
        nxt  = base;
        for (int i = 0; i < 8; i++) begin
            if (nxt[0] ^ data[i])
                nxt = (nxt >> 1) ^ 32'hEDB8_8320;
            else
                nxt = nxt >> 1;
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            rem_q     <= 32'hFFFF_FFFF;
            out_valid <= 1'b0;
        end else begin
            rem_q     <= in_valid ? nxt : base;
            out_valid <= in_valid;
        end
    end

    assign crc = rem_q ^ 32'hFFFF_FFFF;

endmodule

module crc32_stream (
    input  logic        clk,
    input  logic        rst,
    input  logic        start,
    input  logic        in_valid,
    input  logic [7:0]  data,
    output logic        out_valid,
    output logic [31:0] crc
);

    logic [31:0] rem_q;

    // Process one byte, bit 0 first, from the given remainder.
    function automatic logic [31:0] crc_byte(input logic [31:0] r, input logic [7:0] d);
        logic [31:0] x;
        logic        mix;
        x = r;
        for (int i = 0; i < 8; i++) begin
            mix = x[0] ^ d[i];
            x   = {1'b0, x[31:1]};
            if (mix) x = x ^ 32'hEDB8_8320;
        end
        return x;
    endfunction

    logic [31:0] base;
    assign base = start ? 32'hFFFF_FFFF : rem_q;

    always_ff @(posedge clk) begin
        if (rst) begin
            rem_q     <= 32'hFFFF_FFFF;
            out_valid <= 1'b0;
        end else begin
            rem_q     <= in_valid ? crc_byte(base, data) : base;
            out_valid <= in_valid;
        end
    end

    // Remainder resets to all-ones, so crc is 0 after reset.
    assign crc = rem_q ^ 32'hFFFF_FFFF;

endmodule

module crc32_stream (
    input  logic        clk,
