    input  logic        start,
    input  logic        in_valid,
    input  logic [7:0]  data,
    output logic        out_valid,
    output logic [31:0] crc
);

    logic [31:0] rem_q;
    logic [31:0] base;
    logic [31:0] nxt;
    logic        mix;

    always_comb begin
        base = start ? 32'hFFFF_FFFF : rem_q;
        nxt  = base;
        mix  = 1'b0;
        if (in_valid) begin
            for (int i = 0; i < 8; i++) begin
                mix = nxt[0] ^ data[i];
                nxt = {1'b0, nxt[31:1]};
                if (mix) nxt = nxt ^ 32'hEDB8_8320;
            end
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            rem_q     <= 32'hFFFF_FFFF;
            crc       <= 32'h0000_0000;
            out_valid <= 1'b0;
        end else begin
            rem_q     <= nxt;
            crc       <= nxt ^ 32'hFFFF_FFFF;
            out_valid <= in_valid;
        end
    end

endmodule

