            if (do_wr) wr_ptr <= wr_ptr + 1'b1;
            if (do_rd) rd_ptr <= rd_ptr + 1'b1;
            case ({do_wr, do_rd})
                2'b10:   count <= count + 1'b1;
                2'b01:   count <= count - 1'b1;
                default: count <= count;
            endcase
        end
    end

    always_ff @(posedge clk) begin
        if (!rst && do_rd) dout <= mem[rd_ptr];
    end
endmodule

module mul_pipe3 #(
    parameter integer WIDTH = 16
) (
    input  logic                      clk,
    input  logic                      rst,
    input  logic                      in_valid,
    input  logic signed [WIDTH-1:0]   a,
    input  logic signed [WIDTH-1:0]   b,
    output logic                      out_valid,
    output logic signed [2*WIDTH-1:0] product
);

    // Stage 1: operand capture (edge k)
    logic signed [WIDTH-1:0]   a1, b1;
    logic                      v1;
    // Stage 2: multiply (edge k+1)
    logic signed [2*WIDTH-1:0] p2;
    logic                      v2;
    // Stage 3: pipeline register (edge k+2)
    logic signed [2*WIDTH-1:0] p3;
    logic                      v3;

    always_ff @(posedge clk) begin
        a1 <= a;
        b1 <= b;
        p2 <= a1 * b1;
        p3 <= p2;
    end

    // Stage 4 / output register (edge k+3)
    always_ff @(posedge clk) begin
        if (rst) begin
            v1        <= 1'b0;
            v2        <= 1'b0;
            v3        <= 1'b0;
            out_valid <= 1'b0;
            product   <= '0;
        end else begin
            v1        <= in_valid;
            v2        <= v1;
            v3        <= v2;
            out_valid <= v3;
            product   <= v3 ? p3 : '0;
        end
    end

endmodule

module mul_pipe3 #(
    parameter integer WIDTH = 16
) (
    input  logic                      clk,
    input  logic                      rst,
    input  logic                      in_valid,
    input  logic signed [WIDTH-1:0]   a,
    input  logic signed [WIDTH-1:0]   b,
    output logic                      out_valid,
    output logic signed [2*WIDTH-1:0] product
);

    // Stage 1 (after edge k): operands
    logic                    v1;
    logic signed [WIDTH-1:0] a1, b1;
    // Stage 2 (after edge k+1): product
    logic                      v2;
    logic signed [2*WIDTH-1:0] p2;
    // Stage 3 (after edge k+2): product
    logic                      v3;
    logic signed [2*WIDTH-1:0] p3;

    logic signed [2*WIDTH-1:0] prod_full;
    assign prod_full = a1 * b1;

    always_ff @(posedge clk) begin
        if (rst) begin
            v1        <= 1'b0;
            a1        <= '0;
            b1        <= '0;
            v2        <= 1'b0;
            p2        <= '0;
            v3        <= 1'b0;
            p3        <= '0;
            out_valid <= 1'b0;
            product   <= '0;
        end else begin
            v1 <= in_valid;
            a1 <= in_valid ? a : '0;
            b1 <= in_valid ? b : '0;

            v2 <= v1;
            p2 <= v1 ? prod_full : '0;

            v3 <= v2;
            p3 <= p2;

            out_valid <= v3;
            product   <= p3;
        end
    end

endmodule

