module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [F-1:0] slot_flit [5];
    logic [2:0]   slot_src  [5];
    logic [2:0]   cursor    [5];
    logic [4:0]   slot_v;

    logic [2:0] req_o [5];      // requested output per input
    logic [4:0] req_m [5];      // req_m[o][i]
    logic [4:0] gnt_v;
    logic [2:0] gnt_i [5];
    logic [4:0] drain;

    function automatic logic [2:0] succ(input logic [2:0] s);
        succ = (s == 3'd4) ? 3'd0 : s + 3'd1;
    endfunction

    always_comb begin
        logic [1:0] dx, dy;
        logic [2:0] start, idx;
        logic [4:0] rdy;
        logic [F-1:0] fl;
        rdy = '0;
        for (int i = 0; i < 5; i++) begin
            fl = in_flit[i*F +: F];
            dx = fl[F-1 -: 2];
            dy = fl[F-3 -: 2];
            if (dx > X)      req_o[i] = 3'd2;
            else if (dx < X) req_o[i] = 3'd3;
            else if (dy > Y) req_o[i] = 3'd0;
            else if (dy < Y) req_o[i] = 3'd1;
            else             req_o[i] = 3'd4;
        end
        for (int o = 0; o < 5; o++) begin
            drain[o] = slot_v[o] & out_ready[o];
            for (int i = 0; i < 5; i++)
                req_m[o][i] = in_valid[i] && (req_o[i] == 3'(o));
            start = slot_v[o] ? succ(slot_src[o]) : cursor[o];
            gnt_v[o] = 1'b0;
            gnt_i[o] = 3'd0;
            if (!slot_v[o] || out_ready[o]) begin
                for (int k = 0; k < 5; k++) begin
                    idx = start + 3'(k);
                    if (idx >= 3'd5) idx = idx - 3'd5;
                    if (!gnt_v[o] && req_m[o][idx[2:0]]) begin
                        gnt_v[o] = 1'b1;
                        gnt_i[o] = idx;
                    end
                end
            end
            if (gnt_v[o]) rdy[gnt_i[o]] = 1'b1;
        end
        in_ready = rst ? 5'b0 : rdy;
    end

    always_comb begin
        for (int o = 0; o < 5; o++) begin
            out_valid[o] = slot_v[o];
            out_flit[o*F +: F] = slot_v[o] ? slot_flit[o] : '0;
        end
    end

    always_ff @(posedge clk) begin
        for (int o = 0; o < 5; o++) begin
            if (rst) begin
                slot_v[o]     <= 1'b0;
                slot_flit[o]  <= '0;
                slot_src[o]   <= 3'd0;
                cursor[o]     <= 3'd0;
            end else begin
                if (drain[o]) cursor[o] <= succ(slot_src[o]);
                if (gnt_v[o]) begin
                    slot_v[o]    <= 1'b1;
                    slot_flit[o] <= in_flit[gnt_i[o]*F +: F];
                    slot_src[o]  <= gnt_i[o];
                end else if (drain[o]) begin
                    slot_v[o]    <= 1'b0;
                    slot_flit[o] <= '0;
                end
            end
        end
    end
endmodule

