module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    // requested output per input (3 bits each)
    logic [14:0] req_o;
    // one-hot grants per output, packed [o*5 + i]
    logic [24:0] gnt_oh;

    always_comb begin
        logic [1:0] dx, dy;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + F - 1 -: 2];
            dy = in_flit[i*F + F - 3 -: 2];
            if (dx > X)      req_o[i*3 +: 3] = 3'd2;
            else if (dx < X) req_o[i*3 +: 3] = 3'd3;
            else if (dy > Y) req_o[i*3 +: 3] = 3'd0;
            else if (dy < Y) req_o[i*3 +: 3] = 3'd1;
            else             req_o[i*3 +: 3] = 3'd4;
        end
    end

    always_comb begin
        logic [4:0] r;
        r = 5'b0;
        for (int o = 0; o < 5; o++)
            r = r | gnt_oh[o*5 +: 5];
        in_ready = rst ? 5'b0 : r;
    end

    generate
        for (genvar o = 0; o < 5; o++) begin : g_out
            localparam logic [2:0] OID = 3'(o);

            logic         s_v   = 1'b0;
            logic [F-1:0] s_flit = '0;
            logic [2:0]   s_src = 3'd0;
            logic [2:0]   cur   = 3'd0;

            logic [2:0]   succ_src;
            logic [2:0]   start;
            logic [4:0]   req;
            logic [4:0]   oh;
            logic [2:0]   gi;
            logic [F-1:0] sel;
            logic         avail;
            logic         drain;
            logic         found;
            logic [3:0]   sum;

            assign succ_src = (s_src == 3'd4) ? 3'd0 : s_src + 3'd1;
            assign drain    = s_v & out_ready[o];

            always_comb begin
                for (int i = 0; i < 5; i++)
                    req[i] = in_valid[i] && (req_o[i*3 +: 3] == OID);
                start = s_v ? succ_src : cur;
                avail = !s_v || out_ready[o];
                oh    = 5'b0;
                found = 1'b0;
                sum   = 4'd0;
                for (int k = 0; k < 5; k++) begin
                    sum = {1'b0, start} + k[3:0];
                    if (sum >= 4'd5) sum = sum - 4'd5;
                    if (!found && req[sum[2:0]]) begin
                        found = 1'b1;
                        oh[sum[2:0]] = 1'b1;
                    end
                end
                if (!avail) oh = 5'b0;
                gi = {oh[4], oh[2] | oh[3], oh[1] | oh[3]};
                sel = '0;
                for (int i = 0; i < 5; i++)
                    if (oh[i]) sel = sel | in_flit[i*F +: F];
            end

            assign gnt_oh[o*5 +: 5] = oh;
            assign out_valid[o]     = s_v;
            assign out_flit[o*F +: F] = s_v ? s_flit : '0;

            always_ff @(posedge clk) begin
                if (rst) begin
                    s_v    <= 1'b0;
                    s_flit <= '0;
                    s_src  <= 3'd0;
                    cur    <= 3'd0;
                end else begin
                    if (drain) cur <= succ_src;
                    if (|oh) begin
                        s_v    <= 1'b1;
                        s_flit <= sel;
                        s_src  <= gi;
                    end else if (drain) begin
                        s_v    <= 1'b0;
                        s_flit <= '0;
                    end
                end
            end
        end
    endgenerate
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [F-1:0] slot [5];
    logic [2:0]   ptr  [5];   // successor of source of current/last retired flit

    logic [2:0]   req_o [5];
    logic [4:0]   gnt_any;
    logic [2:0]   gnt_src [5];
    logic [4:0]   rdy;

    // Routing
    always_comb begin
        for (int i = 0; i < 5; i++) begin
            logic [1:0] dx, dy;
            dx = in_flit[i*F + F - 1 -: 2];
            dy = in_flit[i*F + F - 3 -: 2];
            if (dx > X)      req_o[i] = 3'd2;
            else if (dx < X) req_o[i] = 3'd3;
            else if (dy > Y) req_o[i] = 3'd0;
            else if (dy < Y) req_o[i] = 3'd1;
            else             req_o[i] = 3'd4;
        end
    end

    // Arbitration
    always_comb begin
        rdy = 5'b0;
        for (int o = 0; o < 5; o++) begin
            gnt_any[o]    = 1'b0;
            gnt_src[o]    = 3'd0;
            if (!rst && (!out_valid[o] || out_ready[o])) begin
                for (int k = 0; k < 5; k++) begin
                    int idx;
                    idx = int'(ptr[o]) + k;
                    if (idx >= 5) idx = idx - 5;
                    if (!gnt_any[o] && in_valid[idx] && (int'(req_o[idx]) == o)) begin
                        gnt_any[o] = 1'b1;
                        gnt_src[o] = 3'(idx);
                        rdy[idx]   = 1'b1;
                    end
                end
            end
        end
    end

    assign in_ready = rdy;

    logic [4:0] v;
    assign out_valid = v;

    always_comb begin
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = v[o] ? slot[o] : '0;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            v <= 5'b0;
            for (int o = 0; o < 5; o++) begin
                slot[o] <= '0;
                ptr[o]  <= 3'd0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (gnt_any[o]) begin
                    v[o]    <= 1'b1;
                    slot[o] <= in_flit[int'(gnt_src[o])*F +: F];
                    ptr[o]  <= (gnt_src[o] == 3'd4) ? 3'd0 : gnt_src[o] + 3'd1;
                end else if (out_ready[o]) begin
                    v[o]    <= 1'b0;
                    slot[o] <= '0;
                end
            end
        end
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    // State: valid, stored flit, scan start pointer (successor of source)
    logic [4:0]       v    = 5'b0;
    logic [5*F-1:0]   slot = '0;
    logic [14:0]      ptr  = 15'b0;

    logic [14:0] req_o;      // requested output per input
    logic [4:0]  gnt_any;    // output accepts a new flit
    logic [14:0] gnt_src;    // chosen source per output
    logic [4:0]  rdy;

    function automatic logic [2:0] wrap5(input logic [2:0] p, input logic [2:0] k);
        logic [3:0] s;
        s = {1'b0, p} + {1'b0, k};
        if (s >= 4'd5) s = s - 4'd5;
        wrap5 = s[2:0];
    endfunction

    // Routing
    genvar gi;
    generate
        for (gi = 0; gi < 5; gi++) begin : g_route
            wire [1:0] dx = in_flit[gi*F + F - 1 -: 2];
            wire [1:0] dy = in_flit[gi*F + F - 3 -: 2];
            assign req_o[gi*3 +: 3] = (dx > X) ? 3'd2 :
                                      (dx < X) ? 3'd3 :
                                      (dy > Y) ? 3'd0 :
                                      (dy < Y) ? 3'd1 : 3'd4;
        end
    endgenerate

    // Arbitration
    always_comb begin
        rdy     = 5'b0;
        gnt_any = 5'b0;
        gnt_src = 15'b0;
        for (int o = 0; o < 5; o++) begin
            if (!rst && (!v[o] || out_ready[o])) begin
                for (int k = 0; k < 5; k++) begin
                    if (!gnt_any[o]
                        && in_valid[wrap5(ptr[o*3 +: 3], 3'(k))]
                        && (req_o[wrap5(ptr[o*3 +: 3], 3'(k))*3 +: 3] == 3'(o))) begin
                        gnt_any[o]        = 1'b1;
                        gnt_src[o*3 +: 3] = wrap5(ptr[o*3 +: 3], 3'(k));
                        rdy[wrap5(ptr[o*3 +: 3], 3'(k))] = 1'b1;
                    end
                end
            end
        end
    end

    assign in_ready  = rdy;
    assign out_valid = v;

    always_comb begin
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = v[o] ? slot[o*F +: F] : '0;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            v    <= 5'b0;
            slot <= '0;
            ptr  <= 15'b0;
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (gnt_any[o]) begin
                    v[o]            <= 1'b1;
                    slot[o*F +: F]  <= in_flit[int'(gnt_src[o*3 +: 3])*F +: F];
                    ptr[o*3 +: 3]   <= wrap5(gnt_src[o*3 +: 3], 3'd1);
                end else if (out_ready[o]) begin
                    v[o]            <= 1'b0;
                    slot[o*F +: F]  <= '0;
                end
            end
        end
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    // State
    logic [4:0]       v    = 5'b0;
    logic [5*F-1:0]   slot = '0;
    logic [14:0]      ptr  = 15'b0;   // scan start per output

    logic [24:0] reqmat;     // [o*5 + i] input i requests output o
    logic [4:0]  gnt_any;
    logic [14:0] gnt_src;
    logic [24:0] rdy_o;      // [o*5 + i] output o grants input i

    function automatic logic [2:0] wrap5(input logic [2:0] p, input logic [2:0] k);
        logic [3:0] s;
        s = {1'b0, p} + {1'b0, k};
        if (s >= 4'd5) s = s - 4'd5;
        wrap5 = s[2:0];
    endfunction

    // Returns {found, index} of first set bit of m scanning cyclically from p
    function automatic logic [3:0] pick(input logic [4:0] m, input logic [2:0] p);
        logic [3:0] r;
        logic [2:0] idx;
        r = 4'b0;
        for (int k = 0; k < 5; k++) begin
            idx = wrap5(p, 3'(k));
            if (!r[3] && m[idx]) r = {1'b1, idx};
        end
        pick = r;
    endfunction

    // Routing
    genvar gi, go;
    generate
        for (gi = 0; gi < 5; gi++) begin : g_route
            wire [1:0] dx = in_flit[gi*F + F - 1 -: 2];
            wire [1:0] dy = in_flit[gi*F + F - 3 -: 2];
            wire [2:0] rq = (dx > X) ? 3'd2 :
                            (dx < X) ? 3'd3 :
                            (dy > Y) ? 3'd0 :
                            (dy < Y) ? 3'd1 : 3'd4;
            for (go = 0; go < 5; go++) begin : g_m
                assign reqmat[go*5 + gi] = in_valid[gi] && (rq == 3'(go));
            end
        end
    endgenerate

    // Per-output arbitration
    generate
        for (go = 0; go < 5; go++) begin : g_arb
            wire       avail = ~rst & (~v[go] | out_ready[go]);
            wire [3:0] pk    = pick(reqmat[go*5 +: 5] & {5{avail}}, ptr[go*3 +: 3]);
            assign gnt_any[go]        = pk[3];
            assign gnt_src[go*3 +: 3] = pk[2:0];
            for (gi = 0; gi < 5; gi++) begin : g_r
                assign rdy_o[go*5 + gi] = pk[3] && (pk[2:0] == 3'(gi));
            end
        end
        for (gi = 0; gi < 5; gi++) begin : g_rdy
            assign in_ready[gi] = rdy_o[gi] | rdy_o[5+gi] | rdy_o[10+gi]
                                | rdy_o[15+gi] | rdy_o[20+gi];
        end
    endgenerate

    assign out_valid = v;

    generate
        for (go = 0; go < 5; go++) begin : g_out
            assign out_flit[go*F +: F] = v[go] ? slot[go*F +: F] : '0;
        end
    endgenerate

    always_ff @(posedge clk) begin
        if (rst) begin
            v    <= 5'b0;
            slot <= '0;
            ptr  <= 15'b0;
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (gnt_any[o]) begin
                    v[o]           <= 1'b1;
                    slot[o*F +: F] <= in_flit[int'(gnt_src[o*3 +: 3])*F +: F];
                    ptr[o*3 +: 3]  <= wrap5(gnt_src[o*3 +: 3], 3'd1);
                end else if (out_ready[o]) begin
                    v[o]           <= 1'b0;
                    slot[o*F +: F] <= '0;
                end
            end
        end
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [F-1:0] slot_flit [5];
    logic [4:0]   slot_v;
    logic [2:0]   slot_src [5];
    logic [2:0]   cur [5];

    logic [2:0]   route [5];
    logic [4:0]   gnt_v;
    logic [2:0]   gnt_i [5];

    function automatic logic [2:0] succ(input logic [2:0] x);
        succ = (x == 3'd4) ? 3'd0 : x + 3'd1;
    endfunction

    always_comb begin
        logic [1:0] dx, dy;
        int idx;
        logic [2:0] start;
        logic avail;
        in_ready = '0;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + F - 1 -: 2];
            dy = in_flit[i*F + F - 3 -: 2];
            if (dx > X)      route[i] = 3'd2;
            else if (dx < X) route[i] = 3'd3;
            else if (dy > Y) route[i] = 3'd0;
            else if (dy < Y) route[i] = 3'd1;
            else             route[i] = 3'd4;
        end
        for (int o = 0; o < 5; o++) begin
            avail = !slot_v[o] || out_ready[o];
            start = (slot_v[o] && out_ready[o]) ? succ(slot_src[o]) : cur[o];
            gnt_v[o] = 1'b0;
            gnt_i[o] = 3'd0;
            if (avail && !rst) begin
                for (int k = 0; k < 5; k++) begin
                    idx = int'(start) + k;
                    if (idx >= 5) idx = idx - 5;
                    if (!gnt_v[o] && in_valid[idx] && (int'(route[idx]) == o)) begin
                        gnt_v[o] = 1'b1;
                        gnt_i[o] = 3'(idx);
                    end
                end
            end
            if (gnt_v[o]) in_ready[gnt_i[o]] = 1'b1;
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            for (int o = 0; o < 5; o++) begin
                slot_v[o]   <= 1'b0;
                slot_flit[o] <= '0;
                slot_src[o] <= 3'd0;
                cur[o]      <= 3'd0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (slot_v[o] && out_ready[o])
                    cur[o] <= succ(slot_src[o]);
                if (gnt_v[o]) begin
                    slot_v[o]    <= 1'b1;
                    slot_flit[o] <= in_flit[int'(gnt_i[o])*F +: F];
                    slot_src[o]  <= gnt_i[o];
                end else if (slot_v[o] && out_ready[o]) begin
                    slot_v[o]    <= 1'b0;
                    slot_flit[o] <= '0;
                end
            end
        end
    end

    always_comb begin
        out_valid = slot_v;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = slot_flit[o];
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    // registered state (packed; defined power-up values)
    logic [5*F-1:0] slot_flit = '0;
    logic [4:0]     slot_v    = '0;
    logic [14:0]    slot_src  = '0;
    logic [14:0]    cur       = '0;

    // combinational
    logic [14:0] route;
    logic [4:0]  gnt_v;
    logic [14:0] gnt_i;
    logic [4:0]  rdy;

    function automatic logic [2:0] succ(input logic [2:0] x);
        succ = (x == 3'd4) ? 3'd0 : (x + 3'd1);
    endfunction

    always_comb begin
        logic [1:0] dx, dy;
        logic [2:0] start;
        logic       avail, found;
        logic [2:0] sel;
        int         idx;

        route = '0;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + F - 1 -: 2];
            dy = in_flit[i*F + F - 3 -: 2];
            if (dx > X)      route[i*3 +: 3] = 3'd2;
            else if (dx < X) route[i*3 +: 3] = 3'd3;
            else if (dy > Y) route[i*3 +: 3] = 3'd0;
            else if (dy < Y) route[i*3 +: 3] = 3'd1;
            else             route[i*3 +: 3] = 3'd4;
        end

        gnt_v = '0;
        gnt_i = '0;
        rdy   = '0;
        for (int o = 0; o < 5; o++) begin
            avail = !slot_v[o] || out_ready[o];
            start = (slot_v[o] && out_ready[o]) ? succ(slot_src[o*3 +: 3]) : cur[o*3 +: 3];
            found = 1'b0;
            sel   = 3'd0;
            if (avail && !rst) begin
                for (int k = 0; k < 5; k++) begin
                    idx = int'(start) + k;
                    if (idx >= 5) idx = idx - 5;
                    if (!found && in_valid[idx] && (int'(route[idx*3 +: 3]) == o)) begin
                        found = 1'b1;
                        sel   = 3'(idx);
                    end
                end
            end
            gnt_v[o]        = found;
            gnt_i[o*3 +: 3] = sel;
            if (found) rdy[sel] = 1'b1;
        end
    end

    assign in_ready  = rdy;
    assign out_valid = slot_v;
    assign out_flit  = slot_flit;

    always_ff @(posedge clk) begin
        if (rst) begin
            slot_v    <= '0;
            slot_flit <= '0;
            slot_src  <= '0;
            cur       <= '0;
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (slot_v[o] && out_ready[o])
                    cur[o*3 +: 3] <= succ(slot_src[o*3 +: 3]);
                if (gnt_v[o]) begin
                    slot_v[o]          <= 1'b1;
                    slot_flit[o*F +: F] <= in_flit[int'(gnt_i[o*3 +: 3])*F +: F];
                    slot_src[o*3 +: 3] <= gnt_i[o*3 +: 3];
                end else if (slot_v[o] && out_ready[o]) begin
                    slot_v[o]          <= 1'b0;
                    slot_flit[o*F +: F] <= '0;
                end
            end
        end
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    function automatic logic [2:0] succ(input logic [2:0] x);
        if (x >= 3'd4) succ = 3'd0;
        else           succ = x + 3'd1;
    endfunction

    // returns {found, index}; first requester scanning cyclically from s
    function automatic logic [3:0] pick(input logic [4:0] req, input logic [2:0] s);
        logic [3:0] t;
        pick = 4'd0;
        for (int k = 4; k >= 0; k--) begin
            t = {1'b0, s} + 4'(k);
            if (t >= 4'd5) t = t - 4'd5;
            if (req[t[2:0]]) pick = {1'b1, t[2:0]};
        end
    endfunction

    // routing per input lane
    logic [14:0] rt;
    genvar gi, go;
    generate
        for (gi = 0; gi < 5; gi++) begin : g_route
            wire [1:0] dx = in_flit[gi*F + F - 1 -: 2];
            wire [1:0] dy = in_flit[gi*F + F - 3 -: 2];
            assign rt[gi*3 +: 3] = (dx > X) ? 3'd2 :
                                   (dx < X) ? 3'd3 :
                                   (dy > Y) ? 3'd0 :
                                   (dy < Y) ? 3'd1 : 3'd4;
        end
    endgenerate

    logic [24:0] gmask;   // per output, 5-bit one-hot grant mask

    generate
        for (go = 0; go < 5; go++) begin : g_out
            logic [F-1:0] flit_r = '0;
            logic         v_r    = 1'b0;
            logic [2:0]   src_r  = 3'd0;
            logic [2:0]   cur_r  = 3'd0;

            logic [4:0] req;
            for (gi = 0; gi < 5; gi++) begin : g_req
                assign req[gi] = in_valid[gi] && (rt[gi*3 +: 3] == 3'(go));
            end

            wire       drain = v_r & out_ready[go];
            wire       avail = ~v_r | out_ready[go];
            wire [2:0] start = drain ? succ(src_r) : cur_r;
            wire [3:0] p     = pick(req, start);
            wire       gnt   = avail & ~rst & p[3];

            assign gmask[go*5 +: 5] = gnt ? (5'b00001 << p[2:0]) : 5'b00000;

            always_ff @(posedge clk) begin
                if (rst) begin
                    v_r    <= 1'b0;
                    flit_r <= '0;
                    src_r  <= 3'd0;
                    cur_r  <= 3'd0;
                end else begin
                    if (drain) cur_r <= succ(src_r);
                    if (gnt) begin
                        v_r    <= 1'b1;
                        flit_r <= in_flit[p[2:0]*F +: F];
                        src_r  <= p[2:0];
                    end else if (drain) begin
                        v_r    <= 1'b0;
                        flit_r <= '0;
                    end
                end
            end

            assign out_valid[go]       = v_r;
            assign out_flit[go*F +: F] = flit_r;
        end
    endgenerate

    assign in_ready = gmask[4:0] | gmask[9:5] | gmask[14:10] | gmask[19:15] | gmask[24:20];
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [F-1:0] slot_flit [5];
    logic [2:0]   slot_src  [5];
    logic [2:0]   cursor    [5];
    logic [4:0]   slot_v;

    // request matrix: req[o][i]
    logic [4:0] req [5];
    logic [4:0] grant [5];
    logic [2:0] gsel [5];
    logic [4:0] gany;

    logic [2:0] dest [5];

    always_comb begin
        for (int i = 0; i < 5; i++) begin
            logic [1:0] dx, dy;
            dx = in_flit[i*F + PAYLOAD_W + 2 +: 2];
            dy = in_flit[i*F + PAYLOAD_W +: 2];
            if (dx > X)      dest[i] = 3'd2;
            else if (dx < X) dest[i] = 3'd3;
            else if (dy > Y) dest[i] = 3'd0;
            else if (dy < Y) dest[i] = 3'd1;
            else             dest[i] = 3'd4;
        end
        for (int o = 0; o < 5; o++) begin
            for (int i = 0; i < 5; i++)
                req[o][i] = in_valid[i] && (dest[i] == 3'(o));
        end
    end

    always_comb begin
        in_ready = '0;
        for (int o = 0; o < 5; o++) begin
            logic [2:0] start;
            logic       avail, drain, found;
            int         idx;
            drain = slot_v[o] && out_ready[o];
            avail = !slot_v[o] || out_ready[o];
            if (drain) start = (slot_src[o] == 3'd4) ? 3'd0 : slot_src[o] + 3'd1;
            else       start = cursor[o];
            grant[o] = '0;
            gsel[o]  = 3'd0;
            found    = 1'b0;
            for (int k = 0; k < 5; k++) begin
                idx = (int'(start) + k) % 5;
                if (!found && avail && !rst && req[o][idx]) begin
                    found = 1'b1;
                    grant[o][idx] = 1'b1;
                    gsel[o] = 3'(idx);
                end
            end
            gany[o] = found;
            in_ready = in_ready | grant[o];
        end
    end

    always_ff @(posedge clk) begin
        for (int o = 0; o < 5; o++) begin
            if (rst) begin
                slot_v[o]    <= 1'b0;
                slot_flit[o] <= '0;
                slot_src[o]  <= 3'd0;
                cursor[o]    <= 3'd0;
            end else begin
                if (slot_v[o] && out_ready[o])
                    cursor[o] <= (slot_src[o] == 3'd4) ? 3'd0 : slot_src[o] + 3'd1;
                if (gany[o]) begin
                    slot_v[o]    <= 1'b1;
                    slot_flit[o] <= in_flit[int'(gsel[o])*F +: F];
                    slot_src[o]  <= gsel[o];
                end else if (slot_v[o] && out_ready[o]) begin
                    slot_v[o]    <= 1'b0;
                    slot_flit[o] <= '0;
                end
            end
        end
    end

    always_comb begin
        out_valid = slot_v;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = slot_flit[o];
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
