                if (gany[o]) begin
                    slot_v[o]    <= 1'b1;
                    slot_flit[o] <= in_flit[int'(gsel[o])*F +: F];
                    slot_src[o]  <= gsel[o];
                end else if (slot_v[o] && out_ready[o]) begin
                    slot_v[o]    <= 1'b0;
                    slot_flit[o] <= '0;
                end
            end
        end
    end

    always_comb begin
        out_valid = slot_v;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = slot_v[o] ? slot_flit[o] : '0;
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [5*F-1:0] slot_flit = '0;
    logic [14:0]    slot_src  = '0;
    logic [14:0]    cursor    = '0;
    logic [4:0]     slot_v    = 5'd0;

    logic [24:0] req;     // req[o*5+i]
    logic [24:0] grant;   // grant[o*5+i]
    logic [14:0] gsel;    // gsel[o*3 +: 3]
    logic [4:0]  gany;
    logic [14:0] dest;    // dest[i*3 +: 3]

    always_comb begin
        logic [1:0] dx, dy;
        logic [2:0] d;
        dx = 2'd0;
        dy = 2'd0;
        d  = 3'd0;
        dest = '0;
        req  = '0;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + PAYLOAD_W + 2 +: 2];
            dy = in_flit[i*F + PAYLOAD_W +: 2];
            if (dx > X)      d = 3'd2;
            else if (dx < X) d = 3'd3;
            else if (dy > Y) d = 3'd0;
            else if (dy < Y) d = 3'd1;
            else             d = 3'd4;
            dest[i*3 +: 3] = d;
        end
        for (int o = 0; o < 5; o++) begin
            for (int i = 0; i < 5; i++)
                req[o*5+i] = in_valid[i] && (int'(dest[i*3 +: 3]) == o);
        end
    end

    always_comb begin
        logic [2:0] start;
        logic [2:0] s;
        logic       avail, drain, found;
        int         idx;
        start = 3'd0;
        s     = 3'd0;
        in_ready = '0;
        gany  = '0;
        grant = '0;
        gsel  = '0;
        for (int o = 0; o < 5; o++) begin
            s     = slot_src[o*3 +: 3];
            drain = slot_v[o] && out_ready[o];
            avail = !slot_v[o] || out_ready[o];
            if (drain) start = (s == 3'd4) ? 3'd0 : s + 3'd1;
            else       start = cursor[o*3 +: 3];
            found = 1'b0;
            for (int k = 0; k < 5; k++) begin
                idx = (int'(start) + k) % 5;
                if (!found && avail && !rst && req[o*5+idx]) begin
                    found = 1'b1;
                    grant[o*5+idx] = 1'b1;
                    gsel[o*3 +: 3] = idx[2:0];
                    in_ready[idx] = 1'b1;
                end
            end
            gany[o] = found;
        end
    end

    always_ff @(posedge clk) begin
        for (int o = 0; o < 5; o++) begin
            if (rst) begin
                slot_v[o]            <= 1'b0;
                slot_flit[o*F +: F]  <= '0;
                slot_src[o*3 +: 3]   <= 3'd0;
                cursor[o*3 +: 3]     <= 3'd0;
            end else begin
                if (slot_v[o] && out_ready[o])
                    cursor[o*3 +: 3] <= (slot_src[o*3 +: 3] == 3'd4) ? 3'd0
                                        : slot_src[o*3 +: 3] + 3'd1;
                if (gany[o]) begin
                    slot_v[o]           <= 1'b1;
                    slot_flit[o*F +: F] <= in_flit[int'(gsel[o*3 +: 3])*F +: F];
                    slot_src[o*3 +: 3]  <= gsel[o*3 +: 3];
                end else if (slot_v[o] && out_ready[o]) begin
                    slot_v[o]           <= 1'b0;
                    slot_flit[o*F +: F] <= '0;
                end
            end
        end
    end

    always_comb begin
        out_valid = slot_v;
        out_flit  = '0;
        for (int o = 0; o < 5; o++)
            if (slot_v[o])
                out_flit[o*F +: F] = slot_flit[o*F +: F];
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]   valid_q;
    logic [F-1:0] flit_q [5];
    logic [2:0]   src_q  [5];
    logic [2:0]   cur_q  [5];

    logic [4:0]   req [5];
    logic [4:0]   gnt_v;
    logic [2:0]   gnt_src [5];
    logic [F-1:0] gnt_flit [5];
    logic [4:0]   rdy;

    function automatic logic [2:0] succ(input logic [2:0] a);
        succ = (a == 3'd4) ? 3'd0 : a + 3'd1;
    endfunction

    always_comb begin
        logic [F-1:0] f;
        logic [1:0] dx, dy;
        logic [2:0] r;
        logic       avail, found;
        logic [2:0] start;
        int         idx;

        for (int o = 0; o < 5; o++) req[o] = 5'b0;
        for (int i = 0; i < 5; i++) begin
            f  = in_flit[i*F +: F];
            dx = f[F-1 -: 2];
            dy = f[F-3 -: 2];
            if (dx > X)      r = 3'd2;
            else if (dx < X) r = 3'd3;
            else if (dy > Y) r = 3'd0;
            else if (dy < Y) r = 3'd1;
            else             r = 3'd4;
            if (in_valid[i]) req[r][i] = 1'b1;
        end

        rdy = 5'b0;
        for (int o = 0; o < 5; o++) begin
            gnt_v[o]    = 1'b0;
            gnt_src[o]  = 3'd0;
            gnt_flit[o] = '0;
            avail = !valid_q[o] || out_ready[o];
            start = valid_q[o] ? succ(src_q[o]) : cur_q[o];
            found = 1'b0;
            for (int k = 0; k < 5; k++) begin
                idx = int'(start) + k;
                if (idx >= 5) idx = idx - 5;
                if (!found && avail && req[o][idx]) begin
                    found       = 1'b1;
                    gnt_v[o]    = 1'b1;
                    gnt_src[o]  = 3'(idx);
                    gnt_flit[o] = in_flit[idx*F +: F];
                    rdy[idx]    = 1'b1;
                end
            end
        end
    end

    assign in_ready = rst ? 5'b0 : rdy;

    always_ff @(posedge clk) begin
        for (int o = 0; o < 5; o++) begin
            if (rst) begin
                valid_q[o] <= 1'b0;
                flit_q[o]  <= '0;
                src_q[o]   <= 3'd0;
                cur_q[o]   <= 3'd0;
            end else begin
                if (valid_q[o] && out_ready[o])
                    cur_q[o] <= succ(src_q[o]);
                if (gnt_v[o]) begin
                    valid_q[o] <= 1'b1;
                    flit_q[o]  <= gnt_flit[o];
                    src_q[o]   <= gnt_src[o];
                end else if (valid_q[o] && out_ready[o]) begin
                    valid_q[o] <= 1'b0;
                    flit_q[o]  <= '0;
                end
            end
        end
    end

    always_comb begin
        out_valid = valid_q;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = valid_q[o] ? flit_q[o] : '0;
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]            valid_q;
    logic [4:0][F-1:0]     flit_q;
    logic [4:0][2:0]       src_q;
    logic [4:0][2:0]       cur_q;

    logic [4:0][4:0]       req;
    logic [4:0]            gnt_v;
    logic [4:0][2:0]       gnt_src;
    logic [4:0][F-1:0]     gnt_flit;
    logic [4:0]            rdy;

    function automatic logic [2:0] succ(input logic [2:0] a);
        succ = (a == 3'd4) ? 3'd0 : (a + 3'd1);
    endfunction

    // request generation
    always_comb begin
        req = '0;
        for (int i = 0; i < 5; i++) begin
            if (in_valid[i]) begin
                if (in_flit[i*F + F - 1 -: 2] > X)
                    req[2][i] = 1'b1;
                else if (in_flit[i*F + F - 1 -: 2] < X)
                    req[3][i] = 1'b1;
                else if (in_flit[i*F + F - 3 -: 2] > Y)
                    req[0][i] = 1'b1;
                else if (in_flit[i*F + F - 3 -: 2] < Y)
                    req[1][i] = 1'b1;
                else
                    req[4][i] = 1'b1;
            end
        end
    end

    // arbitration
    always_comb begin
        rdy      = '0;
        gnt_v    = '0;
        gnt_src  = '0;
        gnt_flit = '0;
        for (int o = 0; o < 5; o++) begin
            for (int k = 0; k < 5; k++) begin
                // compute scan index
                int base;
                int idx;
                base = valid_q[o] ? int'(succ(src_q[o])) : int'(cur_q[o]);
                idx  = base + k;
                if (idx >= 5) idx = idx - 5;
                if (!gnt_v[o] && (!valid_q[o] || out_ready[o]) && req[o][idx]) begin
                    gnt_v[o]    = 1'b1;
                    gnt_src[o]  = 3'(idx);
                    gnt_flit[o] = in_flit[idx*F +: F];
                    rdy[idx]    = 1'b1;
                end
            end
        end
    end

    assign in_ready = rst ? 5'b0 : rdy;

    always_ff @(posedge clk) begin
        for (int o = 0; o < 5; o++) begin
            if (rst) begin
                valid_q[o] <= 1'b0;
                flit_q[o]  <= '0;
                src_q[o]   <= 3'd0;
                cur_q[o]   <= 3'd0;
            end else begin
                if (valid_q[o] && out_ready[o])
                    cur_q[o] <= succ(src_q[o]);
                if (gnt_v[o]) begin
                    valid_q[o] <= 1'b1;
                    flit_q[o]  <= gnt_flit[o];
                    src_q[o]   <= gnt_src[o];
                end else if (valid_q[o] && out_ready[o]) begin
                    valid_q[o] <= 1'b0;
                    flit_q[o]  <= '0;
                end
            end
        end
    end

    assign out_valid = valid_q;

    always_comb begin
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = valid_q[o] ? flit_q[o] : '0;
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]            valid_q = 5'b0;
    logic [4:0][F-1:0]     flit_q  = '0;
    logic [4:0][2:0]       src_q   = '0;
    logic [4:0][2:0]       cur_q   = '0;

    logic [4:0][4:0]       req;
    logic [4:0]            gnt_v;
    logic [4:0][2:0]       gnt_src;
    logic [4:0][F-1:0]     gnt_flit;
    logic [4:0]            rdy;

    function automatic logic [2:0] succ(input logic [2:0] a);
        succ = (a == 3'd4) ? 3'd0 : (a + 3'd1);
    endfunction

    // returns {found, index}
    function automatic logic [3:0] pick(input logic [4:0] rq, input logic [2:0] st);
        logic [3:0] idx;
        logic [3:0] res;
        logic [3:0] kk;
        res = 4'd0;
        for (int k = 0; k < 5; k++) begin
            kk  = k[3:0];
            idx = {1'b0, st} + kk;
            if (idx >= 4'd5) idx = idx - 4'd5;
            if (!res[3] && rq[idx[2:0]]) res = {1'b1, idx[2:0]};
        end
        return res;
    endfunction

    // request generation
    always_comb begin
        req = '0;
        for (int i = 0; i < 5; i++) begin
            if (in_valid[i]) begin
                if (in_flit[i*F + F - 1 -: 2] > X)
                    req[2][i] = 1'b1;
                else if (in_flit[i*F + F - 1 -: 2] < X)
                    req[3][i] = 1'b1;
                else if (in_flit[i*F + F - 3 -: 2] > Y)
                    req[0][i] = 1'b1;
                else if (in_flit[i*F + F - 3 -: 2] < Y)
                    req[1][i] = 1'b1;
                else
                    req[4][i] = 1'b1;
            end
        end
    end

    // arbitration
    always_comb begin
        rdy      = '0;
        gnt_v    = '0;
        gnt_src  = '0;
        gnt_flit = '0;
        for (int o = 0; o < 5; o++) begin
            logic [3:0] pk;
            pk = pick(req[o], valid_q[o] ? succ(src_q[o]) : cur_q[o]);
            if (pk[3] && (!valid_q[o] || out_ready[o])) begin
                gnt_v[o]    = 1'b1;
                gnt_src[o]  = pk[2:0];
                gnt_flit[o] = in_flit[int'(pk[2:0])*F +: F];
                rdy[pk[2:0]] = 1'b1;
            end
        end
    end

    assign in_ready = rst ? 5'b0 : rdy;

    always_ff @(posedge clk) begin
        for (int o = 0; o < 5; o++) begin
            if (rst) begin
                valid_q[o] <= 1'b0;
                flit_q[o]  <= '0;
                src_q[o]   <= 3'd0;
                cur_q[o]   <= 3'd0;
            end else begin
                if (valid_q[o] && out_ready[o])
                    cur_q[o] <= succ(src_q[o]);
                if (gnt_v[o]) begin
                    valid_q[o] <= 1'b1;
                    flit_q[o]  <= gnt_flit[o];
                    src_q[o]   <= gnt_src[o];
                end else if (valid_q[o] && out_ready[o]) begin
                    valid_q[o] <= 1'b0;
                    flit_q[o]  <= '0;
                end
            end
        end
    end

    assign out_valid = valid_q;

    always_comb begin
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = valid_q[o] ? flit_q[o] : '0;
    end
endmodule

module popcount16 (
    input  logic [15:0] x,
    output logic [4:0]  count
);
    logic [1:0] p [8];
    logic [2:0] q [4];
    logic [3:0] r [2];

    always_comb begin
        for (int i = 0; i < 8; i++)
            p[i] = {1'b0, x[2*i]} + {1'b0, x[2*i+1]};
        for (int i = 0; i < 4; i++)
            q[i] = {1'b0, p[2*i]} + {1'b0, p[2*i+1]};
        for (int i = 0; i < 2; i++)
            r[i] = {1'b0, q[2*i]} + {1'b0, q[2*i+1]};
        count = {1'b0, r[0]} + {1'b0, r[1]};
    end
endmodule

module popcount16 (
    input  logic [15:0] x,
    output logic [4:0]  count
);
    logic [4:0] s, c;
    logic a, b, d, e, f;
    logic [3:0] hi;

    always_comb begin
        for (int i = 0; i < 5; i++) begin
            s[i] = x[3*i] ^ x[3*i+1] ^ x[3*i+2];
            c[i] = (x[3*i] & x[3*i+1]) | (x[3*i+2] & (x[3*i] ^ x[3*i+1]));
        end
        a = s[0] ^ s[1] ^ s[2];
        b = (s[0] & s[1]) | (s[2] & (s[0] ^ s[1]));
        d = s[3] ^ s[4] ^ x[15];
        e = (s[3] & s[4]) | (x[15] & (s[3] ^ s[4]));
        count[0] = a ^ d;
        f = a & d;
        hi = 4'(c[0]) + 4'(c[1]) + 4'(c[2]) + 4'(c[3]) + 4'(c[4])
           + 4'(b) + 4'(e) + 4'(f);
        count[4:1] = hi;
    end
endmodule

module popcount16 (
    input  logic [15:0] x,
    output logic [4:0]  count
);
    logic [1:0] s2 [8];
    logic [2:0] s4 [4];
    logic [3:0] s8 [2];

    always_comb begin
        for (int i = 0; i < 8; i++)
            s2[i] = {1'b0, x[2*i]} + {1'b0, x[2*i+1]};
        for (int i = 0; i < 4; i++)
            s4[i] = {1'b0, s2[2*i]} + {1'b0, s2[2*i+1]};
        for (int i = 0; i < 2; i++)
            s8[i] = {1'b0, s4[2*i]} + {1'b0, s4[2*i+1]};
        count = {1'b0, s8[0]} + {1'b0, s8[1]};
    end
endmodule

module popcount16 (
    input  logic [15:0] x,
    output logic [4:0]  count
);
    // Stage 1: five full adders on bits 0..14, bit 15 left over
    logic [4:0] s1, c1;
    always_comb begin
        for (int i = 0; i < 5; i++) begin
            s1[i] = x[3*i] ^ x[3*i+1] ^ x[3*i+2];
            c1[i] = (x[3*i] & x[3*i+1]) | (x[3*i+2] & (x[3*i] ^ x[3*i+1]));
        end
    end

    // Weight-1 column: s1[0..4], x[15] -> 6 bits
    logic a0, a0c, a1, a1c;
    logic b0, b0c;
    logic w1_sum, w1_c1, w1_c2;
    always_comb begin
        // FA(s1[0], s1[1], s1[2])
        a0  = s1[0] ^ s1[1] ^ s1[2];
        a0c = (s1[0] & s1[1]) | (s1[2] & (s1[0] ^ s1[1]));
        // FA(s1[3], s1[4], x[15])
        a1  = s1[3] ^ s1[4] ^ x[15];
        a1c = (s1[3] & s1[4]) | (x[15] & (s1[3] ^ s1[4]));
        // HA(a0, a1)
        w1_sum = a0 ^ a1;
        w1_c1  = a0 & a1;
        // weight-2 carries: a0c, a1c, w1_c1
        w1_c2 = 1'b0;
        b0 = 1'b0;
        b0c = 1'b0;
    end

    // Weight-2 column: c1[0..4], a0c, a1c, w1_c1 -> 8 bits
    logic p0, p0c, p1, p1c, p2, p2c, p3, p3c, p4, p4c;
    logic q0, q0c, q1, q1c;
    logic r0, r0c;
    logic [2:0] unused_w;
    always_comb begin
        // FA(c1[0], c1[1], c1[2])
        p0  = c1[0] ^ c1[1] ^ c1[2];
        p0c = (c1[0] & c1[1]) | (c1[2] & (c1[0] ^ c1[1]));
        // FA(c1[3], c1[4], a0c)
        p1  = c1[3] ^ c1[4] ^ a0c;
        p1c = (c1[3] & c1[4]) | (a0c & (c1[3] ^ c1[4]));
        // FA(a1c, w1_c1, p0)
        p2  = a1c ^ w1_c1 ^ p0;
        p2c = (a1c & w1_c1) | (p0 & (a1c ^ w1_c1));
        // HA(p1, p2)
        q0  = p1 ^ p2;
        q0c = p1 & p2;
        // weight-4 carries: p0c, p1c, p2c, q0c
        p3 = 1'b0; p3c = 1'b0; p4 = 1'b0; p4c = 1'b0;
        q1 = 1'b0; q1c = 1'b0; r0 = 1'b0; r0c = 1'b0;
        unused_w = 3'b0;
    end

    // Weight-4 column: p0c, p1c, p2c, q0c -> up to 4 bits
    logic t0, t0c, t1, t1c;
    always_comb begin
        // FA(p0c, p1c, p2c)
        t0  = p0c ^ p1c ^ p2c;
        t0c = (p0c & p1c) | (p2c & (p0c ^ p1c));
        // HA(t0, q0c)
        t1  = t0 ^ q0c;
        t1c = t0 & q0c;
    end

    // weight-8 bits: t0c, t1c (never both 1 at max count 16 except via bit4)
    assign count[0] = w1_sum;
    assign count[1] = q0;
    assign count[2] = t1;
    assign count[3] = t0c ^ t1c;
    assign count[4] = t0c & t1c;
endmodule

module rr_arbiter4 (
    input  logic       clk,
    input  logic       rst,
    input  logic [3:0] req,
    output logic [3:0] gnt
);
    logic [1:0] last;
    logic [1:0] sel;
    logic       found;

    always_comb begin
        found = 1'b0;
        sel   = last;
        for (int k = 1; k <= 4; k++) begin
            if (!found && req[2'(int'(last) + k)]) begin
                found = 1'b1;
                sel   = 2'(int'(last) + k);
            end
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            gnt  <= 4'b0;
            last <= 2'd3;
        end else if (!found) begin
            gnt <= 4'b0;
        end else begin
            gnt  <= 4'b1 << sel;
            last <= sel;
        end
    end
endmodule

module rr_arbiter4 (
    input  logic       clk,
    input  logic       rst,
    input  logic [3:0] req,
    output logic [3:0] gnt
);
    logic [1:0] last;
    logic [1:0] sel;
    logic       found;

    always_comb begin
        found = 1'b1;
        sel   = last;
        case (last)
            2'd0: begin
                if (req[1])      sel = 2'd1;
                else if (req[2]) sel = 2'd2;
                else if (req[3]) sel = 2'd3;
                else if (req[0]) sel = 2'd0;
                else             found = 1'b0;
            end
            2'd1: begin
                if (req[2])      sel = 2'd2;
                else if (req[3]) sel = 2'd3;
                else if (req[0]) sel = 2'd0;
                else if (req[1]) sel = 2'd1;
                else             found = 1'b0;
            end
            2'd2: begin
                if (req[3])      sel = 2'd3;
                else if (req[0]) sel = 2'd0;
                else if (req[1]) sel = 2'd1;
                else if (req[2]) sel = 2'd2;
                else             found = 1'b0;
            end
            default: begin
                if (req[0])      sel = 2'd0;
                else if (req[1]) sel = 2'd1;
                else if (req[2]) sel = 2'd2;
                else if (req[3]) sel = 2'd3;
                else             found = 1'b0;
            end
        endcase
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            gnt  <= 4'b0000;
            last <= 2'd3;
        end else if (!found) begin
            gnt <= 4'b0000;
        end else begin
            last <= sel;
            case (sel)
                2'd0:    gnt <= 4'b0001;
                2'd1:    gnt <= 4'b0010;
                2'd2:    gnt <= 4'b0100;
                default: gnt <= 4'b1000;
            endcase
        end
    end
endmodule

module rr_arbiter4 (
