            default: begin
                if (req[0])      pick = 2'd0;
                else if (req[1]) pick = 2'd1;
                else if (req[2]) pick = 2'd2;
                else             pick = 2'd3;
            end
        endcase
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            gnt  <= 4'b0;
            last <= 2'd3;
        end else if (!any) begin
            gnt  <= 4'b0;
        end else begin
