module rr_arbiter4 (
    input  logic       clk,
    input  logic       rst,   // synchronous, active high
    input  logic [3:0] req,
    output logic [3:0] gnt
);
    logic [1:0] last;
    logic [1:0] sel;
    logic [1:0] i1, i2, i3;
    logic       any;

    always_comb begin
        any = |req;
        i1  = last + 2'd1;
        i2  = last + 2'd2;
        i3  = last + 2'd3;
        if (req[i1])      sel = i1;
        else if (req[i2]) sel = i2;
        else if (req[i3]) sel = i3;
        else              sel = last;  // last+4 wraps to last
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            gnt  <= 4'b0000;
            last <= 2'd3;
        end else if (!any) begin
            gnt <= 4'b0000;
        end else begin
            gnt  <= 4'b0001 << sel;
            last <= sel;
        end
    end
endmodule

