module seq_detect_1011 (
    input  logic clk,
    input  logic rst,    // synchronous, active high
    input  logic din,    // serial input, one bit per clock
    output logic match
);
    logic [1:0] state;

    always_ff @(posedge clk) begin
        if (rst) begin
            state <= 2'd0;
            match <= 1'b0;
        end else begin
            match <= 1'b0;
            case (state)
                2'd0: state <= din ? 2'd1 : 2'd0;
                2'd1: state <= din ? 2'd1 : 2'd2;
                2'd2: state <= din ? 2'd3 : 2'd0;
                default: begin
                    if (din) begin
                        state <= 2'd1;
                        match <= 1'b1;
                    end else begin
                        state <= 2'd2;
                    end
                end
            endcase
        end
    end
endmodule

