module uart_tx #(
    parameter int CLKS_PER_BIT = 4   // clock cycles per UART bit, >= 2
) (
    input  logic       clk,
    input  logic       rst,
    input  logic       start,
    input  logic [7:0] data,
    output logic       tx,
    output logic       busy
);
    logic [7:0] shift;
    logic [3:0] bit_idx;
    logic [$clog2(CLKS_PER_BIT)-1:0] cnt;

    always_ff @(posedge clk) begin
        if (rst) begin
            tx      <= 1'b1;
            busy    <= 1'b0;
            shift   <= 8'h00;
            bit_idx <= 4'd0;
            cnt     <= '0;
        end else if (!busy) begin
            if (start) begin
                tx      <= 1'b0;
                busy    <= 1'b1;
                shift   <= data;
                bit_idx <= 4'd0;
                cnt     <= '0;
            end
        end else begin
            if (cnt == CLKS_PER_BIT - 1) begin
                cnt <= '0;
                if (bit_idx < 4'd8) begin
                    tx      <= shift[0];
                    shift   <= {1'b0, shift[7:1]};
                    bit_idx <= bit_idx + 4'd1;
                end else if (bit_idx == 4'd8) begin
                    tx      <= 1'b1;
                    bit_idx <= bit_idx + 4'd1;
                end else begin
                    tx   <= 1'b1;
                    busy <= 1'b0;
                end
            end else begin
                cnt <= cnt + 1'b1;
            end
        end
    end
endmodule

