module up_down_counter (
    input  logic       clk,
    input  logic       rst,   // synchronous, active high
    input  logic       en,
    input  logic       up,    // 1 = count up, 0 = count down
    input  logic       load,
    input  logic [7:0] d,
    output logic [7:0] q
);

    always_ff @(posedge clk) begin
        if (rst)
            q <= 8'd0;
        else if (load)
            q <= d;
        else if (en)
            q <= up ? q + 8'd1 : q - 8'd1;
    end

endmodule

